arguments.command:
py -3.12 -I -B -c "import json,pathlib; s=json.loads(pathlib.Path('scratch/t05/schema_inventory.json').read_text()); p=pathlib.Path('scratch/t05');
for n in ['award','city','stadium','injury','club']:
 e=s['entities'][n]; print('\n###',n,e['scalars'],e['lists']); print(' '.join(f"{f['idx']}:{f['code']}:{f['type']}{'?' if f['optional'] else ''}" for f in e['fields'] if not f['list'] and f['type'] not in ('button','label')));
 q=json.loads((p/f'profile_{n}.json').read_text()) if n!='club' else None; print('profile offsets',len(q['columns']) if q else '')
"

